// Sidebar for the /extensions/ pages generated by scripts/fetch-extensions.mjs.
// Built from whatever is on disk, so it tracks the registry without edits here.

import { existsSync, readdirSync, readFileSync } from 'node:fs'
import path from 'node:path'
import type { DefaultTheme } from 'vitepress'

const dir = path.resolve(__dirname, '..', 'extensions')

function title(file: string, fallback: string): string {
  const m = readFileSync(file, 'utf8').match(/^#\s+(.+)$/m)
  return m ? m[1].trim() : fallback
}

const subdirsWithPage = (d: string) =>
  readdirSync(d, { withFileTypes: true })
    .filter((e) => e.isDirectory() && existsSync(path.join(d, e.name, 'index.md')))
    .map((e) => e.name)
    .sort()

export function extensionsSidebar(): DefaultTheme.SidebarItem[] {
  if (!existsSync(path.join(dir, 'index.md'))) return []
  return [
    { text: 'Extensions', link: '/extensions/' },
    ...subdirsWithPage(dir).map((point) => ({
      text: title(path.join(dir, point, 'index.md'), point),
      link: `/extensions/${point}/`,
      collapsed: true,
      // Items are labelled by their registered name, which is what people look up.
      items: subdirsWithPage(path.join(dir, point)).map((name) => ({
        text: name,
        link: `/extensions/${point}/${name}/`,
      })),
    })),
  ]
}
